import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"API 数据源","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"api.md","filePath":"api.md"}'),o={name:"api.md"};function h(i,t,c,n,l,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="api-数据源" tabindex="-1">API 数据源 <a class="header-anchor" href="#api-数据源" aria-label="Permalink to &quot;API 数据源&quot;">​</a></h1><p>EmuTrain 整合了多个权威数据源，为用户提供全面准确的铁路信息。本页列出应用中使用的所有 API 接口。</p><hr><h2 id="车次与交路查询" tabindex="-1">车次与交路查询 <a class="header-anchor" href="#车次与交路查询" aria-label="Permalink to &quot;车次与交路查询&quot;">​</a></h2><h3 id="rail-re" tabindex="-1">Rail.re <a class="header-anchor" href="#rail-re" aria-label="Permalink to &quot;Rail.re&quot;">​</a></h3><p><a href="https://rail.re/" target="_blank" rel="noreferrer">rail.re</a> 是一个专注于中国铁路动车组信息的第三方平台。</p><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>https://api.rail.re/train/{车次}</code></td><td>按车次查询担当动车组与停靠站点</td></tr><tr><td><code>https://api.rail.re/emu/{车组号}</code></td><td>按车组号查询当日担当交路</td></tr></tbody></table><hr><h3 id="railgo" tabindex="-1">RailGo <a class="header-anchor" href="#railgo" aria-label="Permalink to &quot;RailGo&quot;">​</a></h3><p><a href="https://railgo.dev/android.html" target="_blank" rel="noreferrer">railgo.dev</a> 提供丰富的铁路信息查询服务。</p><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>https://emu.data.railgo.zenglingkun.cn/train/{车次}</code></td><td>按车次查询动车组信息</td></tr><tr><td><code>https://emu.data.railgo.zenglingkun.cn/emu/{车组号}</code></td><td>按车组号查询交路信息</td></tr></tbody></table><hr><h3 id="_12306-官方" tabindex="-1">12306 官方 <a class="header-anchor" href="#_12306-官方" aria-label="Permalink to &quot;12306 官方&quot;">​</a></h3><p>中国铁路 12306 官方平台提供的权威接口。</p><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>https://search.12306.cn/search/v1/train/search?keyword={车次}&amp;date={日期}</code></td><td>搜索车次基本信息与始发终到</td></tr><tr><td><code>https://kyfw.12306.cn/otn/leftTicket/queryG?...</code></td><td>查询余票与详细停靠站点</td></tr><tr><td><code>https://kyfw.12306.cn/otn/leftTicketPrice/queryAllPublicPrice?...</code></td><td>查询各席别票价</td></tr><tr><td><code>https://mobile.12306.cn/wxxcx/.../getCarDetail</code></td><td>查询具体担当车型信息</td></tr></tbody></table><hr><h2 id="车站与线路查询" tabindex="-1">车站与线路查询 <a class="header-anchor" href="#车站与线路查询" aria-label="Permalink to &quot;车站与线路查询&quot;">​</a></h2><h3 id="moefactory" tabindex="-1">MoeFactory <a class="header-anchor" href="#moefactory" aria-label="Permalink to &quot;MoeFactory&quot;">​</a></h3><p><a href="https://sharyou.moefactory.com/" target="_blank" rel="noreferrer">sharyou.moefactory.com</a> 与 <a href="https://rail.moefactory.com/" target="_blank" rel="noreferrer">rail.moefactory.com</a> 提供丰富的铁路综合数据。</p><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>https://sharyou.moefactory.com/api/trainNumber/query</code></td><td>按始发终到站查询车次列表</td></tr><tr><td><code>https://sharyou.moefactory.com/api/trainDetails/query</code></td><td>查询车次详细时刻表</td></tr><tr><td><code>https://rail.moefactory.com/api/emuSerialNumber/query</code></td><td>按车组号查询动车组信息</td></tr><tr><td><code>https://rail.moefactory.com/api/station/getBigScreenInfo</code></td><td>获取车站大屏实时信息</td></tr><tr><td><code>https://rail.moefactory.com/api/trainDetails/queryTrainRoutes</code></td><td>查询线路走向图数据</td></tr></tbody></table><hr><h3 id="携程-备用" tabindex="-1">携程（备用） <a class="header-anchor" href="#携程-备用" aria-label="Permalink to &quot;携程（备用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>https://m.ctrip.com/restapi/soa2/14674/json/GetTrainStopTimeInfo</code></td><td>备用车站查询数据源</td></tr></tbody></table><hr><h2 id="数据文件更新" tabindex="-1">数据文件更新 <a class="header-anchor" href="#数据文件更新" aria-label="Permalink to &quot;数据文件更新&quot;">​</a></h2><p>EmuTrain 本地存储了以下数据文件，并可从远程自动更新：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>station.json</code></td><td>车站名称与电报码数据库</td></tr><tr><td><code>train.json</code></td><td>动车组型号与配属信息</td></tr><tr><td><code>coach.json</code></td><td>普速客车车型与配属信息</td></tr><tr><td><code>loco.json</code></td><td>机车型号与配属信息</td></tr></tbody></table><h3 id="更新镜像源" tabindex="-1">更新镜像源 <a class="header-anchor" href="#更新镜像源" aria-label="Permalink to &quot;更新镜像源&quot;">​</a></h3><p>数据文件从以下地址拉取（按优先级排列）：</p><table tabindex="0"><thead><tr><th>镜像</th><th>地址</th></tr></thead><tbody><tr><td><strong>Mirror（默认）</strong></td><td><code>https://gh-proxy.com/https://raw.githubusercontent.com/CrYinLang/EmuTrain/refs/heads/main/</code></td></tr><tr><td><strong>Gitee</strong></td><td><code>https://raw.giteeusercontent.com/CrYinLang/EmuTrain/raw/master/</code></td></tr><tr><td><strong>GitHub</strong></td><td><code>https://raw.githubusercontent.com/CrYinLang/EmuTrain/refs/heads/main/</code></td></tr></tbody></table><p>支持自动回退：首选源失败时，自动尝试下一个镜像。</p><hr><h2 id="图片资源" tabindex="-1">图片资源 <a class="header-anchor" href="#图片资源" aria-label="Permalink to &quot;图片资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://china-emu.cn/Trains/ALL/" target="_blank" rel="noreferrer">china-emu.cn</a></td><td>动车组图鉴图片资源</td></tr></tbody></table><hr><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">数据免责</p><p>所有 API 数据由第三方平台提供，EmuTrain 不对数据准确性负责。<br> 车次查询结果仅供参考，以 12306 官方和实际运行为准。</p></div>',37)])])}const m=a(o,[["render",h]]);export{p as __pageData,m as default};
